// Stratified task sampler for the coordinator plan (DESIGN.md §"Plan (coordinator)"):
// pick at most `max` eligible replay tasks, spread as evenly as possible over the three difficulty
// terciles, with a seeded shuffle inside each tercile so a logged seed reproduces the pick exactly.

export interface SampleTask {
  id: string;
  tercile: 1 | 2 | 3;
  eligible: boolean;
}
```

Hmm — interface says `tasks: { id: string; tercile: 1|2|3; eligible: boolean }[]`. I can define a named exported interface for readability; that's compatible. But careful: adding an exported type isn't a types.ts change. Fine.

Should the type allow tercile null? The interface in the task says `1 | 2 | 3`. Callers (tasks.ts ReplayTask has `tercile: 1|2|3|null`) will need to filter nulls themselves. Keep exactly as specified.

Implementation:

```ts
const TERCILE_ORDER: (1 | 2 | 3)[] = [3, 2, 1];

export function rng(seed: number): () => number { mulberry32 }

export function stratifiedSeed(seed: number, tercile: 1|2|3): number {
  return (Math.imul(seed >>> 0, 0x9e3779b1) ^ Math.imul(tercile, 0x85ebca6b)) >>> 0;
}

function shuffle<T>(items: T[], random: () => number): T[] {
  const out = items.slice();
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [out[i], out[j]] = [out[j]!, out[i]!];
  }
  return out;
}

export function sampleTasks(tasks, opts): string[] {
  const max = Math.max(0, Math.floor(opts.max));
  if (max === 0) return [];
  const pools = new Map<1|2|3, SampleTask[]>([[1,[]],[2,[]],[3,[]]]);
  for (const t of tasks) if (t.eligible) pools.get(t.tercile)!.push(t);
  // even split, remainder to the highest terciles first
  const base = Math.floor(max / 3);
  const rem = max % 3;
  const quota = new Map<1|2|3, number>();
  TERCILE_ORDER.forEach((t, i) => quota.set(t, base + (i < rem ? 1 : 0)));
  // a tercile short of its quota leaves room for the others
  let leftover = max;
  for (const t of TERCILE_ORDER) {
    const take = Math.min(quota.get(t)!, pools.get(t)!.length);
    quota.set(t, take);
    leftover -= take;
  }
  for (let i = 0; leftover > 0; i++) {
    const t = TERCILE_ORDER[i % 3]!;
    const pool = pools.get(t)!;
    if (quota.get(t)! < pool.length) { quota.set(t, quota.get(t)! + 1); leftover--; }
    else if (i >= 3 ... ) break when no capacity anywhere
